window.DOSIK=window.DOSIK||{};DOSIK["reg_tax_procedures"]={"1":[{"t":"table","title":"Audits and summons","head":["Provision","Rule"],"rows":[["IRC §7602(a)(1)","the Secretary is authorized to examine books, papers, records, or other data · that may be relevant or material to ascertaining the correctness of a return"],["IRC §7602(d)(1)","no summons may be issued, and the Secretary may not begin an action to enforce a summons, · with respect to a person for whom a Justice Department referral is in effect"],["IRC §7602(e)","the Secretary may not use financial status or economic reality examination techniques · to determine the existence of unreported income · unless the Secretary has a reasonable indication of a likelihood of such unreported income"]]},{"t":"flow","title":"Notice of deficiency to Tax Court","steps":["IRC §6212(a): a notice of deficiency must be sent to the taxpayer by certified mail or registered mail","IRC §6213(a): a taxpayer generally has 90 days after a notice of deficiency is mailed · (150 days if the notice is addressed to a person outside the United States) · to file a petition with the Tax Court for redetermination of the deficiency","IRC §6213(a): once a taxpayer files a timely petition with the Tax Court, · no assessment of the deficiency may be made until the decision of the Tax Court becomes final, · subject to certain statutory exceptions"]},{"t":"table","title":"Tax Court review","head":["Provision","Rule"],"rows":[["IRC §7442","the Tax Court and its divisions have such jurisdiction as is conferred by Title 26 and certain other specified statutes"],["IRC §7482(a)(1)","the United States Courts of Appeals (other than the Federal Circuit) · have exclusive jurisdiction to review decisions of the Tax Court, · in the same manner as decisions of district courts in civil actions tried without a jury"],["IRC §7483","review of a Tax Court decision is generally obtained by filing a notice of appeal with the clerk of the Tax Court · within 90 days after the decision is entered"],["IRC §7483","if one party files a timely notice of appeal, any other party may take an appeal · by filing a notice of appeal within 120 days after the Tax Court's decision is entered"],["IRC §7482(c)(1)","upon review, a Court of Appeals has the power to affirm, · or, if the decision of the Tax Court is not in accordance with law, to modify or reverse the decision, · with or without remanding the case for a rehearing"],["IRC §7482(b)(1)(A)","for an individual (non-corporate) petitioner seeking redetermination of tax liability, · venue for review generally lies in the circuit of the petitioner's legal residence"]]}],"2":[{"t":"vs","title":"Reducing an understatement","cols":[{"name":"Substantial authority","items":["IRC §6662(d)(2)(B)(i): the amount of an understatement is reduced · for the tax treatment of an item if there is or was substantial authority · for such treatment, regardless of whether it was disclosed on the return","A taxpayer who has substantial authority for the tax treatment of an item · does not need to disclose that item on the return · in order to obtain a reduction in the understatement"]},{"name":"Adequate disclosure","items":["IRC §6662(d)(2)(B)(ii): the amount of an understatement is reduced for an item · if the relevant facts affecting its tax treatment are adequately disclosed in the return · (or in a statement attached to the return)","and there is a reasonable basis for the taxpayer's treatment of the item","A taxpayer who lacks substantial authority for an item's tax treatment · can still reduce the understatement attributable to that item","by adequately disclosing the relevant facts on the return (or an attached statement) · if there is a reasonable basis for the treatment","Disclosure may be made in a statement attached to the return, · not necessarily on the face of the return itself"]}]},{"t":"table","title":"Disclosure and the Secretary's list","head":["Provision","Rule"],"rows":[["IRC §6662(d)(3)","the Secretary may prescribe and publish, in the Federal Register or the Internal Revenue Bulletin, · a list of positions believed not to meet the substantial authority or disclosure standards"],["Published list","Positions on the Secretary's published list under IRC §6662(d)(3) are ones the Secretary believes fail to meet · the substantial authority or adequate-disclosure-with-reasonable-basis standards"],["IRC §6662(b)(6)","for a transaction described in IRC §6662(b)(6) (lacking economic substance), · the relevant facts must be adequately disclosed in the return or an attached statement · to avoid the increased 40 percent penalty rate under §6662(i)"]]},{"t":"table","title":"Recordkeeping and substantiation","head":["Provision","Rule"],"rows":[["IRC §6001","every person liable for any tax must keep such records, render such statements, make such returns, · and comply with such rules and regulations as the Secretary may prescribe"],["IRC §274(d) travel","no deduction is allowed for a traveling expense (including meals and lodging while away from home) · unless the taxpayer substantiates the amount, the time and place of the travel, the business purpose,"],["IRC §274(d) evidence","and the business relationship of the person receiving the benefit, · by adequate records or sufficient corroborating evidence"],["IRC §274(d) scope","the heightened substantiation requirement (amount, time/place, business purpose, and business relationship) · applies not only to travel expenses but also to gifts and to listed property"],["IRC §274(d) regulations","the Secretary may by regulation provide that some or all of the substantiation requirements do not apply · to an expense that does not exceed an amount prescribed in those regulations"]]}],"3":[{"t":"table","title":"Failure-to-file and failure-to-pay additions","head":["Provision","Failure","Addition"],"rows":[["IRC §6651(a)(1)","failure to file a return described in that paragraph · by its due date (including extensions)","5 percent of the tax required to be shown for each month or partial month · the failure continues, up to a maximum of 25 percent, · unless the failure is due to reasonable cause and not willful neglect"],["IRC §6651(a)(2)","failure to pay the amount shown as tax on a return by its payment due date","0.5 percent of that amount per month (or fraction thereof), · up to a maximum of 25 percent, absent reasonable cause"],["IRC §6651(a)(2) timely return","a taxpayer who fails to pay the amount shown as tax on a timely filed return, · without reasonable cause","is subject to this addition"],["IRC §6651(a)(3)","failure to pay an amount stated in a notice and demand · within 21 calendar days of the notice and demand · (10 business days if the amount equals or exceeds $100,000)","can also give rise to an addition to tax, absent reasonable cause"]]},{"t":"def","term":"IRC §6651(g)","text":"a return prepared by the Secretary under §6020(b) is disregarded for purposes of determining · the failure-to-file addition under §6651(a)(1), but is treated as the taxpayer's filed return · for purposes of the failure-to-pay additions under §6651(a)(2) and (3)"},{"t":"vs","title":"Accuracy-related penalty and fraud penalty","cols":[{"name":"IRC §6662 accuracy-related penalty","items":["IRC §6662(b)(1): the 20 percent accuracy-related penalty applies · to the portion of an underpayment attributable to negligence · or disregard of rules or regulations","A taxpayer whose underpayment is due to a substantial understatement of income tax · may be subject to a 20 percent accuracy-related penalty under IRC §6662,","unless an exception (such as adequate disclosure with a reasonable basis, · or substantial authority) applies"]},{"name":"IRC §6663 fraud penalty","items":["IRC §6663(a): if any part of an underpayment of tax is due to fraud, · there is added to the tax an amount equal to 75 percent · of the portion of the underpayment which is attributable to fraud","IRC §6663(b): if the Secretary establishes that any portion · of an underpayment is attributable to fraud, · the entire underpayment is treated as attributable to fraud,","except for any portion the taxpayer establishes, by a preponderance of the evidence, · is not attributable to fraud","A taxpayer whose underpayment is due to fraud is subject to a 75 percent penalty · under IRC §6663 on the portion of the underpayment attributable to the fraud, · rather than the 20 percent penalty under §6662"]}]},{"t":"def","term":"Joint return and the fraud penalty","text":"A married couple filing a joint return will not be subject to the fraud penalty under IRC §6663 with respect to a spouse · unless some part of the underpayment is due to that spouse's own fraud"}]};
